css:
body :where([data-bz-node="hb"]) .bz-block{padding:0}
body :where([data-bz-node="hb"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="hb"]>.bz-container{padding-inline:0}

body [data-bz-node="hb"]{position:relative;overflow:hidden;background:#2b2824;padding:70px 0;min-height:440px;display:flex;flex-direction:column;justify-content:center}
body [data-bz-node="hb"]>.bz-container{max-width:var(--container)}
body [data-bz-node="hb-img"]{position:absolute;inset:0;z-index:0}
body [data-bz-node="hb-img"] figure{margin:0;height:100%}
body [data-bz-node="hb-img"] img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 50%;border-radius:0}
body [data-bz-node="hb-row"]{display:flex;justify-content:flex-end;position:relative;z-index:2}
body [data-bz-node="hb-card"]{grid-column:auto;width:100%;max-width:480px;background:rgba(255,255,255,.96);border:1px solid #fff;padding:36px 36px 34px;box-sizing:border-box}
body [data-bz-node="hb-h"] h2{font:700 30px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0 0 24px}
body [data-bz-node="hb-days"]{display:block}
body [data-bz-node^="hb-day-"]{grid-column:auto;display:block;margin-bottom:13px}
body [data-bz-node^="hb-day-t-"] p{position:relative;padding-left:28px;font:400 13px/1.3 var(--font-body);letter-spacing:.02em;color:var(--ink);margin:0}
body [data-bz-node^="hb-day-t-"] p::before{content:"";position:absolute;left:0;top:0;width:15px;height:15px;background:var(--ink);-webkit-mask:url(/icons/clock.svg) center/15px no-repeat;mask:url(/icons/clock.svg) center/15px no-repeat}
body [data-bz-node="hb-toll"]{display:flex;align-items:center;gap:18px;margin-top:22px}
body [data-bz-node="hb-toll-l"] p{font:700 11px/1 var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="hb-cta"] .bz-btns{margin:0}
body [data-bz-node="hb-cta"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:50px;padding:0 28px;border:0;border-radius:2px;background:var(--accent);color:#fff;font:700 11px/1 var(--font-body);letter-spacing:.18em;text-transform:uppercase;text-decoration:none;height:44px;padding:0 24px;font-size:12px;letter-spacing:.1em;gap:10px}
body [data-bz-node="hb-cta"] .bz-btn::before{content:"";width:14px;height:14px;background:#fff;-webkit-mask:url(/icons/phone.svg) center/14px no-repeat;mask:url(/icons/phone.svg) center/14px no-repeat}
body [data-bz-node="hb-cta"] .bz-btn:hover{background:var(--accent-dark)}
@media (max-width:1100px){body [data-bz-node="hb"]{padding:56px 24px}}
@media (max-width:820px){body [data-bz-node="hb-row"]{justify-content:center}}
@media (max-width:640px){body [data-bz-node="hb"]{padding:40px 20px;min-height:0}body [data-bz-node="hb-card"]{padding:26px 22px}body [data-bz-node="hb-h"] h2{font-size:24px}body [data-bz-node="hb-toll"]{flex-wrap:wrap;gap:12px}}
